import{_ as e,o as r,c as s,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"運行狀態","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/service-status.md","filePath":"zh-HK/user-guide/settings/service-status.md","lastUpdated":1785993908000}'),o={name:"zh-HK/user-guide/settings/service-status.md"};function n(i,t,l,g,p,c){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="運行狀態" tabindex="-1">運行狀態 <a class="header-anchor" href="#運行狀態" aria-label="Permalink to &quot;運行狀態&quot;">​</a></h1><p>管理後臺索引服務，並提供其日誌的實時查看。</p><h2 id="服務控制" tabindex="-1">服務控制 <a class="header-anchor" href="#服務控制" aria-label="Permalink to &quot;服務控制&quot;">​</a></h2><p>狀態卡片會顯示提權索引服務當前的狀態——<strong>安裝中</strong>、<strong>索引中</strong>、<strong>就緒</strong>(附實時檔案/資料夾數量)或<strong>錯誤</strong>——並配有對應的圖示(旋轉指示器、對勾或錯誤標記)。</p><p>只有在服務尚未安裝或出錯時才會出現<strong>安裝並啓動服務</strong>按鈕;一旦安裝完成並正常運行，這個頁面上就沒有手動啓動/停止/解除安裝的控件了——服務預設應該一直在後臺運行。</p><h2 id="日誌" tabindex="-1">日誌 <a class="header-anchor" href="#日誌" aria-label="Permalink to &quot;日誌&quot;">​</a></h2><p>三個 Tab —— <strong>App</strong>、<strong>Hook</strong>、<strong>Service</strong> —— 分別對應 Lertaro 運行的三個處理程序(你實際交互的使用者態 App、鍵盤鉤子處理程序、提權的後臺索引服務)。每個 Tab 顯示對應處理程序的日誌行，按等級着色。</p><ul><li><strong>等級過濾</strong>下拉式方塊 —— 全部 / 錯誤 / 警告 / 信息 / 調試。</li><li><strong>搜尋框</strong> —— 按關鍵詞過濾當前顯示的行，可與等級過濾疊加使用。</li><li><strong>清空日誌</strong> 按鈕 —— 清空當前選中 Tab 的日誌。清空 Service Tab 的日誌會通過服務本身來完成(App 處理程序沒有權限直接改動它);App 和 Hook 的日誌由於是使用者態檔案，可以直接清空。</li></ul><p>排查問題時應該最先看這裏——見<a href="./../troubleshooting.html#還是沒解決">故障排查</a>。</p>',9)])])}const h=e(o,[["render",n]]);export{u as __pageData,h as default};
